      crtWhyFasterBody: "d tem {0} bits; dP e dQ têm apenas {1} e {2} bits — aproximadamente a metade. O caminho direto executa {3} passos de elevar ao quadrado e multiplicar sobre o módulo n de tamanho completo; as duas metades do CRT juntas executam {4} passos combinados sobre os módulos p e q de meio tamanho. O custo da multiplicação escala com o quadrado do comprimento em bits do operando, pelo que reduzir à metade tanto o expoente como o tamanho do operando corta cada multiplicação para cerca de um quarto do custo — resultando em cerca de 4 vezes menos trabalho total para a mesma resposta. É por isso que toda a implementação de produção do RSA decifra desta forma.",
